<div class="container portal-shell">
    <div class="portal-topline"><a href="/dashboard">← Back to my banking</a><span>Account activity</span></div>
    <section class="portal-header"><div><span class="eyebrow">Your accounts</span><h1><?= $escape($data['account']['account_type']) ?> statement.</h1><p>Account holder: <?= $escape($data['account']['display_name']) ?> · <?= $escape($data['account']['account_number']) ?></p></div><span class="status-pill"><?= $escape($data['account']['currency']) ?> <?= $escape($data['account']['balance']) ?></span></section>
    <section class="portal-section" aria-labelledby="statement-activity"><div class="portal-section-heading"><div><span class="eyebrow">Recent activity</span><h2 id="statement-activity">Transactions</h2></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Amount</th></tr></thead><tbody><?php foreach ($data['transactions'] as $item): ?><tr><td><?= $escape(substr((string) $item['posted_at'], 0, 10)) ?></td><td><?= $escape($item['description']) ?></td><td><?= $escape($data['account']['currency']) ?> <?= $escape($item['amount']) ?></td></tr><?php endforeach; ?><?php if ($data['transactions'] === []): ?><tr><td colspan="3">No activity to show.</td></tr><?php endif; ?></tbody></table></div></section>
